function squareIsWhite(coordinates) {
  const letter = coordinates[0];
  const digit = coordinates[1];
  const column = letter.charCodeAt(0) - 'a'.charCodeAt(0) + 1;
  const row = digit.charCodeAt(0) - '0'.charCodeAt(0);
  const sum = column + row;
  return sum % 2 === 1;
}

