function squareIsWhite(coordinates) {
  // Paint the whole board square by square, flipping the colour at each step.
  const columns = 'abcdefgh';
  const white = {};
  for (let r = 1; r <= 8; r++) {
    let isWhite = r % 2 === 0;
    for (const c of columns) {
      white[c + r] = isWhite;
      isWhite = !isWhite;
    }
  }
  return white[coordinates];
}

